import java.util.jar.*;import org.objectweb.asm.*;import org.objectweb.asm.tree.*;
public final class DumpMethod {
 public static void main(String[]args)throws Exception{try(var j=new JarFile(args[0])){var c=new ClassNode();new ClassReader(j.getInputStream(j.getJarEntry("local/lito381/server/ClientSession.class"))).accept(c,ClassReader.SKIP_DEBUG|ClassReader.SKIP_FRAMES);for(var m:c.methods)if(m.name.equals(args[1])){System.out.println(m.name+m.desc);for(var n:m.instructions){String v=n instanceof VarInsnNode a?" local="+a.var:n instanceof MethodInsnNode a?" "+a.owner+"."+a.name+a.desc:n instanceof FieldInsnNode a?" "+a.owner+"."+a.name+":"+a.desc:n instanceof LdcInsnNode a?" "+a.cst:n instanceof JumpInsnNode a?" ->"+m.instructions.indexOf(a.label):n instanceof InvokeDynamicInsnNode a?" "+a.name+java.util.Arrays.toString(a.bsmArgs):n instanceof IntInsnNode a?" "+a.operand:n instanceof TypeInsnNode a?" "+a.desc:"";System.out.println(m.instructions.indexOf(n)+" "+n.getOpcode()+v);}}}}
}
